// Safety Algorithm
// n processes, m resource types, all vectors have length m

Work = copy of Available
Finish[i] = false for every process i

repeat:
    progress = false
    for each process i where Finish[i] == false:
        if Need[i] <= Work:              // every resource type must fit
            Work = Work + Allocation[i]  // Pi finishes, releasing what it held
            Finish[i] = true
            progress = true
    if progress == false:
        stop the loop

if Finish[i] == true for every process i:
    the state is SAFE, the finish order is a safe sequence
else:
    the state is UNSAFE

