// Resource Request Algorithm for a request from process Pi
function requestResources(i, Request):

    if Request > Need[i]:
        return DENY   // Pi asked for more than its declared maximum

    if Request > Available:
        return DENY   // resources are not free right now, Pi must wait

    // pretend to grant the request
    Available = Available-Request
    Allocation[i] = Allocation[i]+Request
    Need[i] = Need[i]-Request

    if runSafetyAlgorithm() == SAFE:
        return GRANT   // keep the update, Pi proceeds with its new resources
    else:
        Available = Available+Request
        Allocation[i] = Allocation[i]-Request
        Need[i] = Need[i]+Request
        return DENY    // undo the pretend update, Pi must wait

